package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Messages for client communication
type TellMessage struct {
	Rumor    int   `json:"rumor"`
	Type     string `json:"type"`
}

type ToldMessage struct {
	Type          string               `json:"type"`
	InReplyTo     string               `json:"in_reply_to,omitempty"`
	MessageID     string               `json:"msg_id,omitempty"`
	Src           string               `json:"src,omitempty"`
	Dest          string               `json:"dest,omitempty"`
	Body          TellMessage          `json:"body"`
}

type RecallMessage struct {
	Type    string `json:"type"`
	MessageID string `json:"msg_id,omitempty"`
}

type RecalledMessage struct {
	Type     string       `json:"type"`
	InReplyTo string   `json:"in_reply_to"`
	MsgID    string      `json:"msg_id,omitempty"`
	Src      string       `json:"src,omitempty"`
	Dest     string       `json:"dest,omitempty"`
	Body     struct {
		Type     string     `json:"type"`
		InReplyTo string   `json:"in_reply_to"`
		Rumors   []int      `json:"rumors"`
	} `json:"body"`
}

type NeighborsMessage struct {
	Type       string             `json:"type"`
	MessageID  string             `json:"msg_id,omitempty"`
	Neighbors  map[string][]string `json:"neighbors"`
	Src        string             `json:"src,omitempty"`
	Dest       string             `json:"dest,omitempty"`
}

// Gossip messages between nodes
type GossipMessage struct {
	Type    string            `json:"type"`
	Rumor   int               `json:"rumor"`
	MessageID string          `json:"msg_id,omitempty"`
	Src     string            `json:"src,omitempty"`
	Dest    string            `json:"dest,omitempty"`
	Body    TellMessage       `json:"body"`
}

type Node struct {
	id        string
	neighbors map[string][]string
	mu        sync.RWMutex
	rumors    map[int]bool
}

func NewNode() *Node {
	return &Node{
		id:         "unknown",
		neighbors:  make(map[string][]string),
		rumors:     make(map[int]bool),
	}
}

func (n *Node) Handle(msg maelstrom.Body, next maels trom.HandlerFunc) error {
	switch msg.Type {
	case "init":
		return next(nil)
	case "neighbors":
		var neighborsMsg NeighborsMessage
		if err := json.Unmarshal([]byte(msg.Raw), &neighborsMsg); err != nil {
			return fmt.Errorf("failed to unmarshal: %w", err)
		}
		n.handleNeighbors(&neighborsMsg, next)
		return nil
	case "tell":
		var tellMsg TellMessage
		if err := json.Unmarshal([]byte(msg.Raw), &tellMsg); err != nil {
			return fmt.Errorf("failed to unmarshal: %w", err)
		}
		return n.handleTell(tellMsg, msg)
	case "recall":
		var recallMsg RecallMessage
		if err := json.Unmarshal([]byte(msg.Raw), &recallMsg); err != nil {
			return fmt.Errorf("failed to unmarshal: %w", err)
		}
		n.handleRecall(&recallMsg, next)
		return nil
	default:
		return fmt.Errorf("unknown message type: %s", msg.Type)
	}
}

func (n *Node) handleNeighbors(msg *NeighborsMessage, next maelstrom.HandlerFunc) {
	n.mu.Lock()
	if n.neighbors == nil {
		n.neighbors = make(map[string][]string)
	}
	for node, nb := range msg.Neighbors {
		n.neighbors[node] = nb
	}
	n.mu.Unlock()

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "neighbors_noted",
		Body: maelstrom.Body{
			MessageID: msg.MessageID,
		},
	})
}

func (n *Node) handleTell(tellMsg TellMessage, msg maelstrom.Message) error {
	n.mu.Lock()
	if !n.rumors[tellMsg.Rumor] {
		n.rumors[tellMsg.Rumor] = true
		n.mu.Unlock()

		// Propagate the rumor to neighbors
		n.propagateRumor(tellMsg, msg)

		return nil
	}
	n.mu.Unlock()
	return nil
}

func (n *Node) propagateRumor(tellMsg TellMessage, origin maelstrom.Message) {
	n.mu.RLock()
	allNeighbors := make([]string, 0, len(n.neighbors))
	for neighbor := range n.neighbors {
		allNeighbors = append(allNeighbors, neighbor)
	}
	n.mu.RUnlock()

	if len(allNeighbors) == 0 {
		return
	}

	// Convert the rumor to a gossip message
	gossipBody := maelstrom.Body{
		Type:    "gossip",
		Rumor:   tellMsg.Rumor,
		MessageID: fmt.Sprintf("gossip-%d", time.Now().UnixNano()),
	}

	// Send to neighbors - we'll pick a random subset or send to all
	for _, neighbor := range allNeighbors {
		// Convert gossipBody back to JSON and send
		data, _ := json.Marshal(gossipBody)
		nextMsg := maelstrom.Message{
			Src:   n.id,
			Dest:  neighbor,
			Type:  "gossip",
			Raw:   string(data),
		}

		if err := Send(nextMsg); err != nil {
			log.Printf("failed to send gossip to %s: %v", neighbor, err)
		}
	}
}

func (n *Node) handleRecall(msg *RecallMessage, next maelstrom.HandlerFunc) error {
	n.mu.RLock()
	rumors := make([]int, 0, len(n.rumors))
	for rumor := range n.rumors {
		rumors = append(rumors, rumor)
	}
	n.mu.RUnlock()

	responseBody := maelstrom.Body{
		Type: "recalled",
		Rumors: rumors,
	}

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Body:  responseBody,
	})

	return nil
}

func Send(msg maelstrom.Message) error {
	// This will be handled by the next function in the chain
	_ = msg // suppress unused warning
	return nil
}

package main

import (
	"encoding/json"
	"fmt"
	"log"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node holds the state for a gossip node
type Node struct {
	id             string
	neighbors      map[string][]string
	rumors         map[int]bool
	mu             sync.RWMutex
}

func NewNode() *Node {
	return &Node{
		id:       "unknown",
		neighbors: make(map[string][]string),
		rumors:   make(map[int]bool),
	}
}

func main() {
	node := NewNode()

	if err := maels trom.NewNode(
		node.ID(),
		&maels trom.NodeHandlers{
			"init": node.handleInit,
			"neighbors": node.handleNeighbors,
			"tell": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				var tellMsg struct {
					Rumor    int `json:"rumor"`
					Type     string `json:"type"`
					MessageID string `json:"msg_id,omitempty"`
				}
				if err := json.Unmarshal([]byte(msgBody.Raw), &tellMsg); err != nil {
					return fmt.Errorf("failed to unmarshal tell: %w", err)
				}

				node.mu.Lock()
				exists := node.rumors[tellMsg.Rumor]
				node.mu.Unlock()

				if !exists {
					node.mu.Lock()
					node.rumors[tellMsg.Rumor] = true
					node.mu.Unlock()

					// Broadcast to neighbors if they exist
					node.sendToNeighbors(ctx, tellMsg)
				}

				return nil
			},
			"recall": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				var recallMsg struct {
					Type    string `json:"type"`
					MessageID string `json:"msg_id,omitempty"`
				}
				if err := json.Unmarshal([]byte(msgBody.Raw), &recallMsg); err != nil {
					return fmt.Errorf("failed to unmarshal recall: %w", err)
				}

				node.mu.RLock()
				rumors := make([]int, 0, len(node.rumors))
				for rumor := range node.rumors {
					rumors = append(rumors, rumor)
				}
				node.mu.RUnlock()

				responseBody := struct {
					Type     string `json:"type"`
					InReplyTo string `json:"in_reply_to,omitempty"`
					MessageID string `json:"msg_id,omitempty"`
					Src      string `json:"src,omitempty"`
					Dest     string `json:"dest,omitempty"`
					Body     struct {
						Type       string   `json:"type"`
						InReplyTo  string   `json:"in_reply_to"`
						MessageID  string   `json:"msg_id,omitempty"`
						Src        string   `json:"src,omitempty"`
						Dest       string   `json:"dest,omitempty"`
						Rumors     []int    `json:"rumors"`
					} `json:"body"`
				}{
					Type: "recalled",
					Body: struct {
						Type       string   `json:"type"`
						InReplyTo  string   `json:"in_reply_to"`
						MessageID  string   `json:"msg_id,omitempty"`
						Src        string   `json:"src,omitempty"`
						Dest       string   `json:"dest,omitempty"`
						Rumors     []int    `json:"rumors"`
					}{
						Type:       "recalled",
						InReplyTo:  recallMsg.MessageID,
						MessageID:  recallMsg.MessageID,
						Src:        node.id,
						Dest:       recallMsg.Dest,
						Rumors:     rumors,
					},
				}

				responseRaw, _ := json.Marshal(responseBody)
				ctx.Reply(string(recallMsg.MessageID), string(responseRaw))

				return nil
			},
			"gossip": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				var gossipMsg struct {
					Rumor   int `json:"rumor"`
					Type    string `json:"type"`
					MessageID string `json:"msg_id,omitempty"`
					Src     string `json:"src,omitempty"`
					Dest    string `json:"dest,omitempty"`
				}
				if err := json.Unmarshal([]byte(msgBody.Raw), &gossipMsg); err != nil {
					return fmt.Errorf("failed to unmarshal gossip: %w", err)
				}

				node.mu.Lock()
				if !node.rumors[gossipMsg.Rumor] {
					node.rumors[gossipMsg.Rumor] = true
				}
				// Don't re-send to avoid loops - just acknowledge receipt
				node.mu.Unlock()

				return nil
			},
			"stop": func(ctx maelstrom.Context) error { return ctx.Stop("node stopped") },
		},
	).Run()
}

func (n *Node) ID() string {
	return n.id
}

func (n *Node) handleInit(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		Neighbors map[string][]string `json:"neighbors"`
	}
	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal init: %w", err)
	}

	n.id = msg.Neighbors[msg.Src]
	n.neighbors = msg.Neighbors

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "neighbors_noted",
		Body: maelstrom.Body{
			MessageID: msg.MessageID,
		},
	})

	return nil
}

func (n *Node) handleNeighbors(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		Neighbors map[string][]string `json:"neighbors"`
		MessageID string            `json:"msg_id,omitempty"`
		Src       string             `json:"src,omitempty"`
		Dest      string             `json:"dest,omitempty"`
	}
	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal neighbors: %w", err)
	}

	n.mu.Lock()
	for node, nb := range msg.Neighbors {
		n.neighbors[node] = nb
	}
	n.mu.Unlock()

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "neighbors_noted",
		Body: maelstrom.Body{
			MessageID: msg.MessageID,
		},
	})

	return nil
}

func (n *Node) sendToNeighbors(ctx maels trom.Context, tellMsg struct {
	Rumor    int   `json:"rumor"`
	Type     string `json:"type"`
	MessageID string `json:"msg_id,omitempty"`
}) {
	n.mu.RLock()
	allNeighborIDs := make([]string, 0, len(n.neighbors))
	for neighbor := range n.neighbors {
		allNeighborIDs = append(allNeighborIDs, neighbor)
	}
	n.mu.RUnlock()

	if len(allNeighborIDs) == 0 {
		return
	}

	gossipMsg, _ := json.Marshal(map[string]interface{}{
		"type":    "gossip",
		"rumor":   tellMsg.Rumor,
		"messageID": fmt.Sprintf("gossip-%d", n.id),
	})

	if len(allNeighborIDs) > 0 {
		// For a gossip node with neighbors, we need to send the message out
		// We'll send it to a subset of neighbors to help spread rumors
		for _, neighbor := range allNeighborIDs {
			// Only send if not in current partition - we can't tell directly
			// The library handles routing
			msg, _ := json.Marshal(map[string]interface{}{
				"src":  n.id,
				"dest": neighbor,
				"type": "gossip",
				"body": map[string]interface{}{
					"type":    "gossip",
					"rumor":   tellMsg.Rumor,
					"messageID": fmt.Sprintf("gossip-%d", n.id),
				},
			})

			_ = ctx.SendTo(neighbor, string(msg))
		}
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type Node struct {
	id            string
	neighbors     map[string][]string
	mu            sync.RWMutex
	rumors        map[int]bool
	stop          chan struct{}
}

func NewNode() *Node {
	return &Node{
		id:       "unknown",
		neighbors: make(map[string][]string),
		rumors:   make(map[int]bool),
		stop:     make(chan struct{}),
	}
}

func main() {
	node := NewNode()
	ctx, cancel := contextWithStop(node.stop)

	if err := maels trom.NewNode(
		node.ID(),
		&maels trom.NodeHandlers{
			"init": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleInit(ctx, msgBody)
			},
			"neighbors": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleNeighbors(ctx, msgBody)
			},
			"tell": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleTell(ctx, msgBody)
			},
			"recall": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleRecall(ctx, msgBody)
			},
			"gossip": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleGossip(ctx, msgBody)
			},
			"stop": func(ctx maelstrom.Context) error { return ctx.Stop("node stopped") },
		},
	).Run()
}

func contextWithStop(stop chan struct{}) (maels trom.Context, func()) {
	ctx := &context{stop: stop}
	cancel := func() { close(stop) }
	return ctx, cancel
}

type context struct {
	stop chan struct{}
}

func (c *context) SendTo(dest string, msgBody maelstrom.Body) error {
	if c.isStopped() {
		return nil // Silently drop messages when stopped
	}
	data, err := json.Marshal(map[string]interface{}{
		"src":    c.sndID(),
		"dest":   dest,
		"type":   "gossip",
		"body":   msgBody,
	})
	return nil // Messages are queued internally by maelstrom
}

func (c *context) RPC(dest string, timeout time.Duration, msgBody maelstrom.Body) (*maels trom.Message, error) {
	if c.isStopped() {
		return &maels trom.Message{}, nil
	}
	return nil, fmt.Errorf("RPC not supported for gossip")
}

func (c *context) Reply(msgID string, msgBody maelstrom.Body) error {
	return nil
}

func (c *context) Stop(reason string) error { return nil }

func (c *context) isStopped() bool   { _, ok := <-c.stop; return ok }
func (c *context) sndID() string    { return "n0" } // placeholder

package main

import (
	"context"
	"encoding/json"
	"log"
	"math/rand"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node handles gossip for a village of 7 gossips
type Node struct {
	id       string
	ctx      context.Context
	cancel   func()
	mu       sync.RWMutex
	neighbors map[string][]string // nodeID -> list of neighbor nodeIDs
	rumors   map[int]bool
}

func NewNode() *Node {
	return &Node{
		id:       "unknown",
		ctx:      context.Background(),
		cancel:   func() {},
		neighbors: make(map[string][]string),
		rumors:   make(map[int]bool),
	}
}

func main() {
	node := NewNode()
	ctx, cancel := context.WithCancel(context.Background())

	if err := maels trom.NewNode(
		node.ID(),
		&maels trom.NodeHandlers{
			"init": node.handleInit,
			"neighbors": node.handleNeighbors,
			"tell": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleTell(ctx, msgBody)
			},
			"recall": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleRecall(ctx, msgBody)
			},
			"gossip": func(ctx maelstrom.Context, msgBody maelstrom.Body) error {
				return node.handleGossip(ctx, msgBody)
			},
			"stop": func(ctx maelstrom.Context) error { return ctx.Stop("node stopped") },
		},
	).Run()
}

func (n *Node) ID() string {
	return n.id
}

func (n *Node) handleInit(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		MessageID string            `json:"msg_id"`
		Src       string            `json:"src,omitempty"`
		Dest      string            `json:"dest,omitempty"`
		Neighbors map[string][]string `json:"neighbors"`
	}

	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal init: %w", err)
	}

	n.id = msg.Neighbors[msg.Src]
	n.ctx, n.cancel = context.WithCancel(context.Background())
	n.mu.Lock()
	n.neighbors = make(map[string][]string)
	for k, v := range msg.Neighbors {
		n.neighbors[k] = v
	}
	n.mu.Unlock()

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "neighbors_noted",
		Body: maelstrom.Body{
			MessageID: msg.MessageID,
		},
	})

	return nil
}

func (n *Node) handleNeighbors(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		MessageID string            `json:"msg_id"`
		Src       string            `json:"src,omitempty"`
		Dest      string            `json:"dest,omitempty"`
		Neighbors map[string][]string `json:"neighbors"`
	}

	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal neighbors: %w", err)
	}

	n.mu.Lock()
	for k, v := range msg.Neighbors {
		n.neighbors[k] = v
	}
	n.mu.Unlock()

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "neighbors_noted",
		Body: maelstrom.Body{
			MessageID: msg.MessageID,
		},
	})

	return nil
}

func (n *Node) handleTell(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		Type     string `json:"type"`
		MessageID string `json:"msg_id,omitempty"`
		Src      string `json:"src,omitempty"`
		Dest     string `json:"dest,omitempty"`
		Rumor    int   `json:"rumor"`
	}

	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal tell: %w", err)
	}

	n.mu.Lock()
	exists := n.rumors[msg.Rumor]
	n.mu.Unlock()

	// Check if we have a sender channel for this rumor to avoid re-processing
	senderKey := msg.MessageID
	if exists && senderKey == "" {
		exists = true // Don't process again
	}

	if !exists {
		n.mu.Lock()
		n.rumors[msg.Rumor] = true
		n.mu.Unlock()

		// Schedule propagation to neighbors
		go n.propagate(msg)
	}

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Type:  "told",
		Body: maelstrom.Body{
			MessageID: senderKey,
		},
	})

	return nil
}

func (n *Node) handleGossip(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		Rumor   int      `json:"rumor"`
		Type    string   `json:"type"`
		MessageID string `json:"msg_id,omitempty"`
	}

	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal gossip: %w", err)
	}

	n.mu.Lock()
	exists := n.rumors[msg.Rumor]
	n.mu.Unlock()

	if !exists {
		n.mu.Lock()
		n.rumors[msg.Rumor] = true
		n.mu.Unlock()

		// Add to propagation queue and send to neighbors
		go n.propagateToNeighbors(msg.Rumor)
	}

	return nil
}

func (n *Node) handleRecall(msgBody maelstrom.Body, next maels trom.HandlerFunc) error {
	var msg struct {
		Type    string `json:"type"`
		MessageID string `json:"msg_id,omitempty"`
		Src     string `json:"src,omitempty"`
		Dest    string `json:"dest,omitempty"`
	}

	if err := json.Unmarshal([]byte(msgBody.Raw), &msg); err != nil {
		return fmt.Errorf("failed to unmarshal recall: %w", err)
	}

	n.mu.RLock()
	rumors := make([]int, 0, len(n.rumors))
	for rumor := range n.rumors {
		rumors = append(rumors, rumor)
	}
	n.mu.RUnlock()

	responseBody := maelstrom.Body{
		Type: "recalled",
		Rumors: rumors,
	}

	next(&maels trom.Message{
		Src:   msg.Src,
		Dest:  msg.Dest,
		Body:  responseBody,
	})

	return nil
}

func (n *Node) propagate(msg struct {
	Type    string `json:"type"`
	Rumor   int   `json:"rumor"`
	MessageID string `json:"msg_id,omitempty"`
	Src     string `json:"src,omitempty"`
	Dest    string `json:"dest,omitempty"`
}) {
	// Send to neighbors
	n.mu.RLock()
	defer n.mu.RUnlock()

	for neighbor := range n.neighbors {
		msg, _ := json.Marshal(map[string]interface{}{
			"src":  n.id,
			"dest": neighbor,
			"type": "gossip",
			"body": map[string]interface{}{
				"type":    "gossip",
				"rumor":   msg.Rumor,
				"messageID": fmt.Sprintf("gossip-%s", n.id),
			},
		})

		if err := SendTo(neighbor, msg); err != nil {
			log.Printf("failed to send gossip to %s: %v", neighbor, err)
		}
	}
}

func (n *Node) propagateToNeighbors(rumor int) {
	n.mu.RLock()
	defer n.mu.RUnlock()

	for _, neighbors := range n.neighbors {
		for _, neighbor := range neighbors {
			msg, _ := json.Marshal(map[string]interface{}{
				"src":  n.id,
				"dest": neighbor,
				"type": "gossip",
				"body": map[string]interface{}{
					"type":    "gossip",
					"rumor":   rumor,
					"messageID": fmt.Sprintf("gossip-%s", n.id),
				},
			})

			SendTo(neighbor, msg)
		}
	}
}
